class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            dp[i][0] = i;
        }
        for (int j = 0; j <= n; j++) {
            dp[0][j] = j;
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    int replace = dp[i - 1][j - 1];
                    int delete = dp[i - 1][j];
                    int insert = dp[i][j - 1];
                    dp[i][j] = 1 + Math.min(replace, Math.min(delete, insert));
                }
            }
        }
        return dp[m][n];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[] dp = new int[n + 1];
        for (int j = 0; j <= n; j++) {
            dp[j] = j;
        }
        for (int i = 1; i <= m; i++) {
            int diagonal = dp[0];
            dp[0] = i;
            for (int j = 1; j <= n; j++) {
                int oldTop = dp[j];
                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {
                    dp[j] = diagonal;
                } else {
                    int replace = diagonal;
                    int delete = oldTop;
                    int insert = dp[j - 1];
                    dp[j] = 1 + Math.min(replace, Math.min(delete, insert));
                }
                diagonal = oldTop;
            }
        }
        return dp[n];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        Integer[][] memo = new Integer[word1.length() + 1][word2.length() + 1];
        return solve(word1, word2, 0, 0, memo);
    }

    private int solve(String word1, String word2, int i, int j, Integer[][] memo) {
        if (i == word1.length()) {
            return word2.length() - j;
        }
        if (j == word2.length()) {
            return word1.length() - i;
        }
        if (memo[i][j] != null) {
            return memo[i][j];
        }
        if (word1.charAt(i) == word2.charAt(j)) {
            memo[i][j] = solve(word1, word2, i + 1, j + 1, memo);
        } else {
            int insert = solve(word1, word2, i, j + 1, memo);
            int delete = solve(word1, word2, i + 1, j, memo);
            int replace = solve(word1, word2, i + 1, j + 1, memo);
            memo[i][j] = 1 + Math.min(replace, Math.min(delete, insert));
        }
        return memo[i][j];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[][] suffix = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            suffix[i][n] = m - i;
        }
        for (int j = 0; j <= n; j++) {
            suffix[m][j] = n - j;
        }
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (word1.charAt(i) == word2.charAt(j)) {
                    suffix[i][j] = suffix[i + 1][j + 1];
                } else {
                    int delete = suffix[i + 1][j];
                    int insert = suffix[i][j + 1];
                    int replace = suffix[i + 1][j + 1];
                    suffix[i][j] = 1 + Math.min(replace, Math.min(delete, insert));
                }
            }
        }
        return suffix[0][0];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[][] distance = new int[m + 1][n + 1];
        for (int[] row : distance) {
            java.util.Arrays.fill(row, Integer.MAX_VALUE);
        }
        java.util.ArrayDeque<int[]> deque = new java.util.ArrayDeque<>();
        distance[0][0] = 0;
        deque.addFirst(new int[] {0, 0});
        while (!deque.isEmpty()) {
            int[] state = deque.removeFirst();
            int i = state[0];
            int j = state[1];
            int current = distance[i][j];
            if (i < m && j < n) {
                int diagonalCost = word1.charAt(i) == word2.charAt(j) ? 0 : 1;
                relax(distance, deque, i + 1, j + 1, current + diagonalCost, diagonalCost);
            }
            if (i < m) {
                relax(distance, deque, i + 1, j, current + 1, 1);
            }
            if (j < n) {
                relax(distance, deque, i, j + 1, current + 1, 1);
            }
        }
        return distance[m][n];
    }

    private void relax(int[][] distance, java.util.ArrayDeque<int[]> deque, int nextI, int nextJ, int nextCost, int edgeCost) {
        if (nextCost >= distance[nextI][nextJ]) {
            return;
        }
        distance[nextI][nextJ] = nextCost;
        if (edgeCost == 0) {
            deque.addFirst(new int[] {nextI, nextJ});
        } else {
            deque.addLast(new int[] {nextI, nextJ});
        }
    }
}
